class TestRoundtripNormalization:
    """Tests for the GET->SET round-trip helpers (_normalize_config_for_roundtrip).

    These canonicalize a config fetched from HA into the modern 2024.10+ shape:
    plural root list keys and per-trigger 'trigger:' type keys.
    """

    def test_normalize_trigger_keys_platform_to_trigger(self):
        """Legacy per-trigger 'platform' is canonicalized to modern 'trigger'."""
        triggers = [
            {"platform": "state", "entity_id": "binary_sensor.motion"},
            {"trigger": "time", "at": "07:00:00"},  # already modern, untouched
        ]

        result = _normalize_trigger_keys(triggers)

        assert result[0]["trigger"] == "state"
        assert "platform" not in result[0]
        assert result[1]["trigger"] == "time"

    def test_normalize_trigger_keys_drops_platform_when_trigger_present(self):
        """When both 'platform' and 'trigger' exist, 'trigger' wins and the legacy
        'platform' alias is dropped (HA strict schema rejects extra keys)."""
        triggers = [{"platform": "state", "trigger": "time"}]

        result = _normalize_trigger_keys(triggers)

        assert result[0]["trigger"] == "time"
        assert "platform" not in result[0]

    def test_normalize_trigger_keys_passes_non_dict_through(self):
        """Malformed non-dict trigger items pass through untouched (no AttributeError)."""
        # Deliberately malformed input to exercise the defensive guard.
        result = _normalize_trigger_keys([{"platform": "state"}, "oops", None])  # type: ignore[list-item]
        assert result[0] == {"trigger": "state"}
        assert result[1] == "oops"
        assert result[2] is None

    def test_roundtrip_produces_plural_roots_and_modern_trigger_keys(self):
        """A GET-shaped config is canonicalized to plural roots + 'trigger:' keys."""
        config = {
            "alias": "Morning",
            "trigger": [{"platform": "time", "at": "07:00:00"}],
            "condition": [{"condition": "state", "entity_id": "x", "state": "on"}],
            "action": [{"action": "light.turn_on"}],
        }

        result = _normalize_config_for_roundtrip(config)

        assert "triggers" in result and "trigger" not in result
        assert "conditions" in result and "condition" not in result
        assert "actions" in result and "action" not in result
        # Per-trigger key canonicalized to modern 'trigger:'.
        assert result["triggers"][0]["trigger"] == "time"
        assert "platform" not in result["triggers"][0]


class TestConflictingRootKeys:
    """_detect_conflicting_root_keys surfaces a warning when a config carries both
    a singular alias and its canonical plural with different values (normalization
    keeps the plural and would otherwise silently drop the singular)."""

    def test_detects_conflict_with_differing_values(self):
        warnings = _detect_conflicting_root_keys(
            {"trigger": [{"trigger": "state"}], "triggers": []}
        )
        assert len(warnings) == 1
        assert "trigger" in warnings[0] and "triggers" in warnings[0]

    def test_no_conflict_when_values_equal(self):
        assert _detect_conflicting_root_keys({"trigger": [], "triggers": []}) == []

    def test_no_conflict_for_single_form(self):
        assert _detect_conflicting_root_keys({"triggers": [{"trigger": "state"}]}) == []

    def test_detects_all_three_pairs(self):
        warnings = _detect_conflicting_root_keys(
            {
                "trigger": [1],
                "triggers": [2],
                "action": [1],
                "actions": [2],
                "condition": [1],
                "conditions": [2],
            }
        )
        assert len(warnings) == 3

    def test_non_dict_returns_empty(self):
        assert _detect_conflicting_root_keys(["not", "a", "dict"]) == []

"""Unit tests for `_get_local_backup_agent_id` in the backup tools module.

Regression coverage for the hardcoded `hassio.local` bug that broke `ha_backup_*`
tools on HA Core installs (which only register `backup.local`).
"""

import json
from unittest.mock import AsyncMock, MagicMock, patch

import pytest
from fastmcp.exceptions import ToolError

from ha_mcp.tools.backup import (
    _backup_protected,
    _get_local_backup_agent_id,
    _summarize_backup,
    list_backups,
    restore_backup,
)


class TestBackupProtected:
    """`_backup_protected` derives the encrypted flag from the per-agent map."""

    def test_any_agent_protected_makes_it_protected(self):
        entry = {
            "agents": {
                "backup.local": {"protected": False},
                "google_drive.cloud": {"protected": True},
            }
        }
        assert _backup_protected(entry) is True

    def test_all_agents_unprotected(self):
        entry = {"agents": {"backup.local": {"protected": False}}}
        assert _backup_protected(entry) is False

    def test_missing_agents_is_unknown(self):
        assert _backup_protected({}) is None

    def test_no_agent_reports_protected_is_unknown(self):
        # agents present but none carry the field → unknown, not "unprotected".
        assert _backup_protected({"agents": {"backup.local": {"size": 1}}}) is None

    def test_non_dict_agents_is_unknown(self):
        assert _backup_protected({"agents": ["unexpected"]}) is None


def _ws_client(agents_payload: dict) -> AsyncMock:
    """Build a mock WS client whose `send_command("backup/agents/info")` returns the given payload."""
    ws = AsyncMock()
    ws.send_command.return_value = agents_payload
    return ws


class TestGetLocalBackupAgentId:
    @pytest.mark.asyncio
    async def test_core_only_returns_backup_local(self):
        """HA Core install (only `backup.local` registered) returns `backup.local`."""
        ws = _ws_client(
            {
                "success": True,
                "result": {"agents": [{"agent_id": "backup.local", "name": "local"}]},
            }
        )
        assert await _get_local_backup_agent_id(ws) == "backup.local"

    @pytest.mark.asyncio
    async def test_supervised_only_returns_hassio_local(self):
        """HA Supervised install (only `hassio.local` registered) returns `hassio.local`."""
        ws = _ws_client(
            {
                "success": True,
                "result": {"agents": [{"agent_id": "hassio.local", "name": "local"}]},
            }
        )
        assert await _get_local_backup_agent_id(ws) == "hassio.local"

    @pytest.mark.asyncio
    async def test_both_present_prefers_hassio_local(self):
        """When both agents are registered, prefer `hassio.local` (Supervisor)."""
        ws = _ws_client(
            {
                "success": True,
                "result": {
                    "agents": [
                        {"agent_id": "backup.local", "name": "local"},
                        {"agent_id": "hassio.local", "name": "local"},
                    ],
                },
            }
        )
        assert await _get_local_backup_agent_id(ws) == "hassio.local"

    @pytest.mark.asyncio
    async def test_only_remote_agents_raises(self):
        """No agent named `local` raises `ToolError` listing the available agents."""
        ws = _ws_client(
            {
                "success": True,
                "result": {
                    "agents": [
                        {"agent_id": "google_drive.cloud", "name": "Google Drive"}
                    ]
                },
            }
        )
        with pytest.raises(ToolError) as exc_info:
            await _get_local_backup_agent_id(ws)
        error = json.loads(str(exc_info.value))
        assert "No local backup agent found" in error["error"]["message"]
        assert error["available_agents"] == ["google_drive.cloud"]

    @pytest.mark.asyncio
    async def test_empty_agent_list_raises(self):
        """Empty agent list raises `ToolError` with an actionable suggestion."""
        ws = _ws_client({"success": True, "result": {"agents": []}})
        with pytest.raises(ToolError) as exc_info:
            await _get_local_backup_agent_id(ws)
        error = json.loads(str(exc_info.value))
        assert "No backup agents registered" in error["error"]["message"]

    @pytest.mark.asyncio
    async def test_send_command_failure_raises(self):
        """A `success=False` response from HA raises `ToolError`."""
        ws = _ws_client({"success": False, "error": "WS error"})
        with pytest.raises(ToolError) as exc_info:
            await _get_local_backup_agent_id(ws)
        error = json.loads(str(exc_info.value))
        assert "Failed to enumerate backup agents" in error["error"]["message"]

    @pytest.mark.asyncio
    async def test_malformed_local_entry_filtered_out(self):
        """An agent with `name=local` but missing `agent_id` is filtered, not returned as None."""
        ws = _ws_client(
            {
                "success": True,
                "result": {
                    "agents": [
                        {"name": "local"},  # malformed — no agent_id
                        {"agent_id": "backup.local", "name": "local"},
                    ],
                },
            }
        )
        assert await _get_local_backup_agent_id(ws) == "backup.local"

