            "not silently passed"
        )

    def test_greater_than_reversed_recency(self):
        """``X.last_changed > now() - <delta>`` (changed within window) recency math is flagged."""
        config = {
            "condition": [
                {
                    "condition": "template",
                    "value_template": "{{ states.sensor.x.last_changed > now() - timedelta(minutes=5) }}",
                }
