        with pytest.raises(ToolError) as exc_info:
            AutomationConfigTools._validate_required_fields(
                {
                    "alias": "Movie Snapshot",
                    "triggers": [],
                    "actions": [
                        {
                            "action": "scene.create",
                            "data": {"scene_id": "movie_night"},
                        }
                    ],
