                {"name": "state", "required": True},
                {
                    "type": "expandable",
                    "name": "advanced_options",
                    "schema": [{"name": "availability", "required": False}],
                },
            ],
        }

        form_data = _handle_form_step("flow-1", step, remaining)

        assert form_data == {
            "state": "{{ 1 }}",
            "advanced_options": {
                "availability": "{{ has_value('sensor.x') }}",
