                "tags": ["Mixed"],
                "description": "d",
                "annotations": {"readOnlyHint": True},
            },
            {
                "name": "ha_foo",  # toggleable, disabled
                "title": "Foo",
                "primary_tag": "Mixed",
                "tags": ["Mixed"],
                "description": "d",
                "annotations": {"readOnlyHint": True},
            },
        ]
        result = run_script(
