            settings_script,
            initial_html=MIN_DOM,
            # Populated tools so init renders silently (an empty list would fire a
            # "No tools found" error toast during settle and clobber our toast).
            fetch_map={
                **DEFAULT_FETCHES,
                "/api/settings/tools": {
