                            {
                                "name": "ha_get_state",
                                "title": "Get State",
                                "primary_tag": "Test",
                                "annotations": {"readOnlyHint": True},
                            },
                        ],
                        "states": {"ha_get_state": "enabled"},
                        "env_pinned": {},
                        "read_only_exempt": [],
                    },
