                    "tools": [tool],
                    "states": {},
                    "env_pinned": {},
                    "read_only_exempt": [],
                },
            },
            "/api/settings/features": {
                "status": 200,
                "json": {
                    "flags": {
                        "enable_tool_security_policies": {
                            "value": True,
                            "origin": "default",
                            "editable": True,
                            "type": "bool",
                        }
                    },
                    "beta_sub_flags": [],
                    "is_addon": False,
                },
            },
            "/api/policy/config": {
                "responses": [
                    {"status": 200, "json": {"rules": [{"tool_name": "ha_get_state"}]}},
