    @pytest.mark.asyncio
    async def test_post_merges_into_existing_file(
        self, monkeypatch: MonkeyPatch, tmp_path: Path
    ) -> None:
        """Partial POST merges with existing prefs (RMW under lock)."""
        path = tmp_path / "theme_prefs.json"
