"""Unit tests for the leading-underscore strip helper in util_helpers.

`public_fields` centralises the convention that ha-mcp tool layers
enrich entity / area dicts with internal fields like ``_hidden_by`` /
``_aliases`` so downstream branches can rank without re-querying the
registry, and those fields must not leak through public tool returns
(see the projection path in tools_search.py).

The non-mutating half of the contract is load-bearing: at the call site
the source dict is read again right after the copy
(``apply_hidden_penalty(100, entity.get("_hidden_by"))``), so a
``public_fields`` that stripped the source in place would silently skip
the hidden-entity score penalty while the output still looked clean —
these tests pin the contract.
"""

from ha_mcp.tools.util_helpers import public_fields


class TestPublicFields:
    """Locks down `public_fields` non-mutating shallow-copy contract."""

    def test_returns_new_dict(self):
        d = {"entity_id": "x", "_hidden_by": "user"}
        result = public_fields(d)
        assert result is not d, "must return new dict"

    def test_does_not_mutate_source(self):
        d = {"entity_id": "x", "_hidden_by": "user"}
        public_fields(d)
        # Source must still have the underscore key.
        assert "_hidden_by" in d

    def test_strips_underscore_keys(self):
        d = {"a": 1, "_b": 2, "c": 3, "_aliases": ["x"]}
        assert public_fields(d) == {"a": 1, "c": 3}

    def test_shallow_only_list_values_shared(self):
        # Documents the shallow-copy contract: list/dict values are
        # shared, so a downstream mutation of the value would affect
        # the source.
        shared_list = ["a", "b"]
        d = {"items": shared_list, "_hidden_by": "user"}
        result = public_fields(d)
        assert result["items"] is shared_list

    def test_handles_int_keys(self):
        d = {1: "one", "_hidden_by": "x", "name": "n"}
        # int keys (can't startswith) pass through untouched.
        assert public_fields(d) == {1: "one", "name": "n"}

    def test_empty_dict(self):
        assert public_fields({}) == {}

    def test_no_underscore_keys(self):
        d = {"a": 1, "b": 2}
        result = public_fields(d)
        assert result == d
        assert result is not d  # still a copy

"""Unit tests for embedded-mode detection in ``ha_mcp._version`` (issue #1527).

``_version.py`` is deliberately standalone (it imports only ``os`` / ``logging``
/ ``importlib.metadata``), so it is loaded here in isolation via importlib —
without pulling in the full ``ha_mcp`` package — and exercised purely through the
environment. The load-in-isolation keeps this test in the hermetic local tier.

The key interaction: on HAOS the HA core container carries ``SUPERVISOR_TOKEN``,
so ``is_running_in_addon()`` would wrongly report True in-process. Setting
``HA_MCP_EMBEDDED`` must flip it back to False so add-on-only code paths (direct
Supervisor log fetch, add-on settings routing) do not apply to the embedded
server, which is a plain admin client of HA core.
"""

from __future__ import annotations

import importlib.util
import pathlib

import pytest

_VERSION_PATH = (
    pathlib.Path(__file__).resolve().parents[3] / "src" / "ha_mcp" / "_version.py"
)


def _load_version_module():
    spec = importlib.util.spec_from_file_location(
        "_ha_mcp_version_under_test", _VERSION_PATH
    )
    assert spec is not None and spec.loader is not None
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


@pytest.fixture
def version_mod():
    return _load_version_module()


@pytest.fixture(autouse=True)
def _clean_env(monkeypatch):
    monkeypatch.delenv("SUPERVISOR_TOKEN", raising=False)
    monkeypatch.delenv("HA_MCP_EMBEDDED", raising=False)
    yield


class TestIsEmbedded:
    def test_false_when_unset(self, version_mod):
        assert version_mod.is_embedded() is False

    def test_true_when_set(self, version_mod, monkeypatch):
        monkeypatch.setenv("HA_MCP_EMBEDDED", "1")
        assert version_mod.is_embedded() is True


class TestIsRunningInAddon:
    def test_false_with_no_env(self, version_mod):
        assert version_mod.is_running_in_addon() is False

    def test_true_with_supervisor_token_only(self, version_mod, monkeypatch):
        monkeypatch.setenv("SUPERVISOR_TOKEN", "tok")
        assert version_mod.is_running_in_addon() is True

    def test_false_when_embedded_even_with_supervisor_token(
        self, version_mod, monkeypatch
    ):
        # The load-bearing case: HAOS core container has SUPERVISOR_TOKEN, but
        # the in-process server sets HA_MCP_EMBEDDED and must NOT be an add-on.
        monkeypatch.setenv("SUPERVISOR_TOKEN", "tok")
        monkeypatch.setenv("HA_MCP_EMBEDDED", "1")
        assert version_mod.is_embedded() is True
        assert version_mod.is_running_in_addon() is False

    def test_false_when_embedded_without_supervisor_token(
        self, version_mod, monkeypatch
    ):
        monkeypatch.setenv("HA_MCP_EMBEDDED", "1")
        assert version_mod.is_running_in_addon() is False

