    out = await fn(yaml_path="rest", file="configuration.yaml")

    assert out["success"] is True
    assert out["count"] == 1
    assert out["files_searched"] == 1
    assert out["matches"] == [
        {
            "file": "configuration.yaml",
            "yaml_path": "rest",
            "content": "method: GET\n",
        }
    ]


