    list_files, _ = _bracket_dir("svc[a].yaml")

    fn, _ = await _make_tool(
        {
            "list_files": list_files,
            "read_file": {
                "success": True,
                "path": "packages/svc[a].yaml",
                "content": "...",
                "subtree": None,
